+int Dot11DecryptAddKeys(
+    PDOT11DECRYPT_CONTEXT ctx,
+    DOT11DECRYPT_KEY_ITEM keys[],
+    const size_t keys_nr)
+{
+    int success = 0;
+
+    if (ctx == NULL || keys == NULL) {
+        ws_warning("NULL context or NULL keys array");
+        return 0;
+    }
+
+    for (size_t i = 0; i < keys_nr; i++) {
+        if (ctx->keys_nr >= DOT11DECRYPT_MAX_KEYS_NR) {
+            ws_warning("Reached maximum number of decryption keys (%d), ignoring remaining %zu keys from DSB",
+                       DOT11DECRYPT_MAX_KEYS_NR, keys_nr - i);
+            break;
+        }
+        if (Dot11DecryptValidateKey(keys + i) == true) {
+            if (keys[i].KeyType == DOT11DECRYPT_KEY_TYPE_WPA_PWD && keys[i].UserPwd.SsidLen > 0) {
+                Dot11DecryptRsnaPwd2Psk(&keys[i].UserPwd, keys[i].KeyData.Wpa.Psk);
+                keys[i].KeyData.Wpa.PskLen = DOT11DECRYPT_WPA_PWD_PSK_LEN;
+            }
+            memcpy(&ctx->keys[ctx->keys_nr], &keys[i], sizeof(keys[i]));
+            ctx->keys_nr++;
+            success++;
+        }
+    }
+
+    ws_debug("Added %d keys from DSB, total keys now %zu", success, ctx->keys_nr);
+    return success;
+}
