+/*
+ * Convert a decryption_key_t (from parse_key_string()) into a
+ * DOT11DECRYPT_KEY_ITEM.  Returns true on success, false if the key
+ * type is unrecognised.  Used by both the preference/UAT path and
+ * the pcapng DSB path so the conversion logic lives in one place.
+ */
+static bool
+dk_to_key_item(const decryption_key_t *dk, DOT11DECRYPT_KEY_ITEM *key_item)
+{
+  memset(key_item, 0, sizeof(*key_item));
+
+  switch (dk->type) {
+  case DOT11DECRYPT_KEY_TYPE_WEP:
+    key_item->KeyType = DOT11DECRYPT_KEY_TYPE_WEP;
+    memcpy(key_item->KeyData.Wep.WepKey, dk->key->data, dk->key->len);
+    key_item->KeyData.Wep.WepKeyLen = dk->key->len;
+    return true;
+
+  case DOT11DECRYPT_KEY_TYPE_WPA_PWD:
+    key_item->KeyType = DOT11DECRYPT_KEY_TYPE_WPA_PWD;
+    memcpy(key_item->UserPwd.Passphrase, dk->key->data, dk->key->len);
+    key_item->UserPwd.PassphraseLen = dk->key->len;
+    key_item->UserPwd.SsidLen = 0;
+    if ((dk->ssid != NULL) && (dk->ssid->len <= DOT11DECRYPT_WPA_SSID_MAX_LEN)) {
+      memcpy(key_item->UserPwd.Ssid, dk->ssid->data, dk->ssid->len);
+      key_item->UserPwd.SsidLen = dk->ssid->len;
+    }
+    return true;
+
+  case DOT11DECRYPT_KEY_TYPE_WPA_PSK:
+    key_item->KeyType = DOT11DECRYPT_KEY_TYPE_WPA_PSK;
+    memcpy(key_item->KeyData.Wpa.Psk, dk->key->data, dk->key->len);
+    key_item->KeyData.Wpa.PskLen = dk->key->len;
+    return true;
+
+  case DOT11DECRYPT_KEY_TYPE_TK:
+    key_item->KeyType = DOT11DECRYPT_KEY_TYPE_TK;
+    memcpy(key_item->Tk.Tk, dk->key->data, dk->key->len);
+    key_item->Tk.Len = dk->key->len;
+    key_item->Tk.mld = dk->tk_mld;
+    if (dk->tk_mld) {
+      memcpy(key_item->Tk.ap_mld_mac, dk->ap_mld_mac, 6);
+      memcpy(key_item->Tk.sta_mld_mac, dk->sta_mld_mac, 6);
+    }
+    return true;
+
+  case DOT11DECRYPT_KEY_TYPE_MSK:
+    key_item->KeyType = DOT11DECRYPT_KEY_TYPE_MSK;
+    memcpy(key_item->Msk.Msk, dk->key->data, dk->key->len);
+    key_item->Msk.Len = dk->key->len;
+    return true;
+
+  default:
+    return false;
+  }
+}
