+static void
+ieee80211_secrets_block_callback(const void *secrets, unsigned size)
+{
+    const char *data = (const char *)secrets;
+    const char *data_end = data + size;
+    DOT11DECRYPT_KEYS_COLLECTION *keys = g_new(DOT11DECRYPT_KEYS_COLLECTION, 1);
+    keys->nKeys = 0;
+
+    /* Parse line by line - format: "key_type","key_value" */
+    while (data < data_end && keys->nKeys < DOT11DECRYPT_MAX_KEYS_NR) {
+        /* Skip whitespace and newlines */
+        while (data < data_end && (*data == '\n' || *data == '\r' || *data == ' ' || *data == '\t'))
+            data++;
+        if (data >= data_end)
+            break;
+
+        /* Find end of line */
+        const char *line_end = data;
+        while (line_end < data_end && *line_end != '\n' && *line_end != '\r')
+            line_end++;
+
+        /* Parse: "key_type","key_value"
+         * Find first quoted field */
+        const char *p = data;
+        if (*p != '"') {
+            data = line_end;
+            continue;
+        }
+        p++; /* skip opening quote */
+        const char *key_type_start = p;
+        while (p < line_end && *p != '"')
+            p++;
+        if (p >= line_end) {
+            data = line_end;
+            continue;
+        }
+        size_t key_type_len = p - key_type_start;
+        p++; /* skip closing quote */
+
+        /* Skip comma */
+        if (p < line_end && *p == ',')
+            p++;
+
+        /* Find second quoted field */
+        if (p >= line_end || *p != '"') {
+            data = line_end;
+            continue;
+        }
+        p++; /* skip opening quote */
+        const char *key_value_start = p;
+        while (p < line_end && *p != '"')
+            p++;
+        if (p >= line_end) {
+            data = line_end;
+            continue;
+        }
+        size_t key_value_len = p - key_value_start;
+
+        /* Look up key type using wep_type_vals (value_string: value->string) */
+        char *key_type_str = g_strndup(key_type_start, key_type_len);
+        char *key_value_str = g_strndup(key_value_start, key_value_len);
+
+        /* Reverse lookup: find the enum value for this key type string */
+        uint8_t key_type = 0;
+        bool found = false;
+        for (const value_string *vs = wep_type_vals; vs->strptr != NULL; vs++) {
+            if (g_ascii_strcasecmp(vs->strptr, key_type_str) == 0) {
+                key_type = (uint8_t)vs->value;
+                found = true;
+                break;
+            }
+        }
+
+        if (!found) {
+            ws_warning("Unknown 802.11 key type in DSB: \"%s\"", key_type_str);
+            g_free(key_type_str);
+            g_free(key_value_str);
+            data = line_end;
+            continue;
+        }
+
+        decryption_key_t *dk = parse_key_string(key_value_str, key_type, NULL);
+        if (dk != NULL) {
+            DOT11DECRYPT_KEY_ITEM key;
+            if (dk_to_key_item(dk, &key)) {
+                keys->Keys[keys->nKeys] = key;
+                keys->nKeys += 1;
+            }
+            free_key_string(dk);
+        }
+
+        g_free(key_type_str);
+        g_free(key_value_str);
+        data = line_end;
+    }
+
+    if (keys->nKeys > 0) {
+        Dot11DecryptAddKeys(&dot11decrypt_ctx, keys->Keys, keys->nKeys);
+    }
+    g_free(keys);
+}
